namespace ModularCA.Auth.Models;

/// <summary>
/// Request model for <c>POST /api/v1/auth/claim</c>: a one-time claim token and the password it
/// sets. No username: the token names the account.
/// </summary>
public class ClaimAccountRequest
{
    /// <summary>The claim token, as generated by <c>--new-claim-token</c> or <c>--issue-claim-token</c>.</summary>
    public string Token { get; set; } = string.Empty;

    /// <summary>The password to set, which must meet the configured password policy.</summary>
    public string NewPassword { get; set; } = string.Empty;

    /// <summary>Confirmation of the new password; must match <see cref="NewPassword"/>.</summary>
    public string ConfirmNewPassword { get; set; } = string.Empty;
}
